SELECT 
  FROM tc_model
 WHERE model_name = #{modelName}
   AND model_version = #{modelVersion}

SELECT 
  FROM tc_model


        AND model_name LIKE CONCAT('%', #{modelNameLike}, '%')


        AND protocol_type = #{protocolType, typeHandler=org.apache.ibatis.type.EnumTypeHandler}


        AND status = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler}


ORDER BY model_key DESC

    LIMIT #{limit} OFFSET #{offset}
